function pick(list){
  const out=[];
  for(const s of list){
    const c=files.filter(f=>f===s+'.glb'||f===s+'-lowpoly.glb'||f===s+'-skinned.glb'||f.startsWith(s+'-'));
    out.push([s,c]);
