}
const groups=[['KNOWN',pick(known)],['STRUCT',pick(stems)]];
function parse(buf){
  const dv=new DataView(buf.buffer,buf.byteOffset,buf.byteLength);
  let off=12,json=null;
  while(off+8<=buf.length){
    const len=dv.getUint32(off,true), type=dv.getUint32(off+4,true), start=off+8;
    if(type===0x4E4F534A) json=JSON.parse(Buffer.from(buf.buffer,start,len).toString('utf8'));
